#include <iostream>
#include <vector>

struct Widget {
    static int copies, moves;
    Widget() = default;
    Widget(const Widget&) { ++copies; }        // 拷贝
    Widget(Widget&&) { ++moves; }              // 非 noexcept 移动
};
int Widget::copies = 0, Widget::moves = 0;

int main() {
    std::vector<Widget> v;
    v.reserve(1);
    v.push_back(Widget());   // ① 临时对象移动进容器 -> moves=1
    v.push_back(Widget());   // ② 临时移动(moves+1)；扩容搬移旧元素时移动可能抛，
                             //    为保强异常安全改用拷贝 -> copies=1
    std::cout << "copies=" << Widget::copies << " moves=" << Widget::moves << '\n';
    std::cout << "结论：非 noexcept 移动时，扩容退化为拷贝，copies 增大\n";
}
